import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"52 - Broker WebSocket Factory","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/52-broker-factory-implementation.md","filePath":"developers/design-documentation/52-broker-factory-implementation.md"}'),d={name:"developers/design-documentation/52-broker-factory-implementation.md"};function c(n,e,i,s,l,p){return t(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="_52-broker-websocket-factory" tabindex="-1">52 - Broker WebSocket Factory <a class="header-anchor" href="#_52-broker-websocket-factory" aria-label="Permalink to &quot;52 - Broker WebSocket Factory&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><code>websocket_proxy/broker_factory.py</code> dynamically loads the active broker&#39;s streaming adapter and optionally wraps it in a connection pool. This factory is specific to real-time broker feeds; normalized REST order/data services perform their own broker-module imports.</p><h2 id="adapter-resolution" tabindex="-1">Adapter Resolution <a class="header-anchor" href="#adapter-resolution" aria-label="Permalink to &quot;Adapter Resolution&quot;">​</a></h2><p>For broker key <code>&lt;broker&gt;</code>, the factory:</p><ol><li>Checks the in-process adapter class registry.</li><li>Imports <code>broker.&lt;broker&gt;.streaming.&lt;broker&gt;_adapter</code>.</li><li>Resolves <code>&lt;Broker&gt;WebSocketAdapter</code> using the current class-name convention.</li><li>Falls back to <code>websocket_proxy.&lt;broker&gt;_adapter</code> for legacy adapter placement.</li><li>Registers the resolved class for later reuse or raises <code>ValueError</code> when no adapter is available.</li></ol><p>Plugin presence does not by itself prove a working streaming adapter. <code>broker/*/plugin.json</code> is the broker configuration inventory; the factory still requires an importable adapter for WebSocket use.</p><h2 id="pooling" tabindex="-1">Pooling <a class="header-anchor" href="#pooling" aria-label="Permalink to &quot;Pooling&quot;">​</a></h2><p><code>create_broker_adapter()</code> uses <code>ENABLE_CONNECTION_POOLING</code> unless a caller overrides it.</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ENABLE_CONNECTION_POOLING</code></td><td style="text-align:right;"><code>true</code></td><td>Return a pooled wrapper</td></tr><tr><td><code>MAX_SYMBOLS_PER_WEBSOCKET</code></td><td style="text-align:right;"><code>1000</code></td><td>Capacity allocated to one connection</td></tr><tr><td><code>MAX_WEBSOCKET_CONNECTIONS</code></td><td style="text-align:right;"><code>3</code></td><td>Maximum connections per user/broker pool</td></tr></tbody></table><p>Pools are keyed by broker and user. The wrapper preserves the adapter interface for initialize, connect, disconnect, subscribe, unsubscribe, unsubscribe-all, status, and publishing operations. Pool cleanup removes the global registry entry.</p><h2 id="zeromq-fan-in" tabindex="-1">ZeroMQ Fan-In <a class="header-anchor" href="#zeromq-fan-in" aria-label="Permalink to &quot;ZeroMQ Fan-In&quot;">​</a></h2><p>All pooled connections share one thread-safe ZeroMQ publisher. The proxy SUB socket binds <code>ZMQ_HOST:ZMQ_PORT</code>; the shared and standalone adapter PUB sockets connect to it. This fixed fan-in direction allows multiple adapter publishers without port-scan or bind races.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>broker connection 1 --\\</span></span>
<span class="line"><span>broker connection 2 ----&gt; shared PUB connects ---&gt; proxy SUB binds ---&gt; clients</span></span>
<span class="line"><span>broker connection 3 --/</span></span></code></pre></div><h2 id="token-refresh-and-recovery" tabindex="-1">Token Refresh And Recovery <a class="header-anchor" href="#token-refresh-and-recovery" aria-label="Permalink to &quot;Token Refresh And Recovery&quot;">​</a></h2><p>Connection pools recognize common authentication failures such as 401, 403, expired token, and invalid credentials. Recovery can force adapter re-initialization with current auth data. Re-authentication with unchanged plaintext broker/feed tokens must preserve the existing shared feed rather than replacing it because encrypted values differ.</p><h2 id="current-plugin-inventory" tabindex="-1">Current Plugin Inventory <a class="header-anchor" href="#current-plugin-inventory" aria-label="Permalink to &quot;Current Plugin Inventory&quot;">​</a></h2><p>There are 36 <code>broker/*/plugin.json</code> directories, covering 34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin for paper trading:</p><p><code>aliceblue</code>, <code>angel</code>, <code>arrow</code>, <code>compositedge</code>, <code>definedge</code>, <code>deltaexchange</code>, <code>dhan</code>, <code>dhan_sandbox</code>, <code>firstock</code>, <code>fivepaisa</code>, <code>fivepaisaxts</code>, <code>flattrade</code>, <code>fyers</code>, <code>groww</code>, <code>hdfcsecurities</code>, <code>hdfcsky</code>, <code>ibulls</code>, <code>iifl</code>, <code>iiflcapital</code>, <code>indmoney</code>, <code>jainamxts</code>, <code>kotak</code>, <code>motilal</code>, <code>mstock</code>, <code>nubra</code>, <code>paytm</code>, <code>pocketful</code>, <code>rmoney</code>, <code>samco</code>, <code>shoonya</code>, <code>tradejini</code>, <code>tradesmart</code>, <code>upstox</code>, <code>wisdom</code>, <code>zebu</code>, and <code>zerodha</code>.</p><p>Only <code>deltaexchange</code> declares <code>broker_type: crypto</code> and <code>leverage_config: true</code>; the other 35 declare <code>broker_type: IN_stock</code> with <code>leverage_config: false</code>.</p><p>Individual broker symbol limits and depth capabilities are adapter/upstream concerns and must not be inferred from the generic 1000-by-3 pool defaults.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>websocket_proxy/broker_factory.py</code></td><td>Resolution, class registry, pooled wrapper</td></tr><tr><td><code>websocket_proxy/connection_manager.py</code></td><td>Pools, subscription distribution, shared publisher</td></tr><tr><td><code>websocket_proxy/base_adapter.py</code></td><td>Common adapter interface and standalone publisher</td></tr><tr><td><code>websocket_proxy/server.py</code></td><td>Authentication, subscription index, SUB binder, client fan-out</td></tr><tr><td><code>broker/*/streaming/</code></td><td>Broker-specific upstream implementations</td></tr></tbody></table><p>See <a href="./authentication-platforms">WebSockets Architecture</a> and the <a href="./../../api-documentation/v1/websockets">WebSocket API</a>.</p>`,24)])])}const u=o(d,[["render",c]]);export{b as __pageData,u as default};
